INSERT INTO feature VALUES('circle-loop-space','identity','The circle''s loop space is the integers','presented-circle','implemented','unique','dependent provers','`Path[.A = Circle](Base, Base)` is checked equivalent to `Int`, the book''s π₁(S¹) ≃ ℤ, replayed and readmitted. A word of loops reaches its normal form in one pass, and a path moves along a closed word in one step, linear in its letters in both engines.','core-checker kernel-core','corpus/model/identity/circle.gandr corpus/model/identity/loop-space.gandr','corpus/model/identity/circle.gandr',NULL);
